"""Create a small calculation notebook and safe inline evidence receipt input."""
import json
from pathlib import Path
import nbformat

ROOT = Path(__file__).resolve().parent
a=json.loads((ROOT/"assumptions.json").read_text())
r=json.loads((ROOT/"results.json").read_text())

notebook=nbformat.v4.new_notebook(cells=[
    nbformat.v4.new_markdown_cell("# Trading app economics: illustrative scenarios\n\nNo observed customers, billing, retention, or capacity measurements exist. USD scenarios dated 3 November 2026; months are relative to commercial launch, not today's calendar. This is a table-only calculation companion to the chat answer, not a business forecast."),
    nbformat.v4.new_markdown_cell("## Context and assumptions\n\nA $39 weighted monthly subscription; 60 AI calls per paying user with 5,000 input and 2,000 billable output tokens each; three limited active-free users subsidized per payer; market-data allowance of $3/payer without a commercial quote. All workload, customer growth, pricing, churn, acquisition, staffing and capacity inputs are planning assumptions. Published vendor prices anchor only some inputs. Model excludes tax, upfront development/security/legal launch work, unquoted mandatory regulatory/commercial charges, and customers' broker trading costs. Gross MRR is not profit or cash collected."),
    nbformat.v4.new_code_cell("import json\nfrom pathlib import Path\nfrom model import load, build\nassumptions = load()\nresults = build(assumptions)\nprint(json.dumps({'average_price': results['average_monthly_price'], 'variable_components': results['variable_components']}, indent=2))"),
    nbformat.v4.new_markdown_cell("## Scale economics\n\nDirect service costs include the modeled free-user subsidy, support, fees/refunds, and shared operating allowance. Operating balance also subtracts engineering/admin and acquisition allowances. Scale acquisition budget assumes gross monthly additions equal to 10% of opening payer count at $30 each; with 5% churn this approximates 5% net monthly growth, not a measured funnel."),
    nbformat.v4.new_code_cell("for row in results['scale']:\n    print(f\"{row['paying_users']:,} payers | gross MRR ${row['gross_monthly_subscription_revenue']:,.0f} | direct ${row['direct_service_cost']:,.0f} | direct/payer ${row['direct_cost_per_payer']:.2f} | operating balance ${row['modeled_operating_balance_before_tax']:,.0f}\")"),
    nbformat.v4.new_markdown_cell("## Growth scenarios\n\nPaying users = prior paying users × 95% + gross new paying users. Gross acquisition schedules are explicit assumptions in assumptions.json. Expected counts may be fractional and are rounded for display. Revenue shown is end-month gross subscription run rate. Any modeled monthly/cumulative balances assume end-month payers pay a full month and ignore invoice timing/proration; they are not a cash-flow forecast."),
    nbformat.v4.new_code_cell("for row in results['growth']:\n    if row['month_after_commercial_launch'] in [3, 6, 12]:\n        print(f\"{row['scenario']} month {row['month_after_commercial_launch']}: approximately {row['paying_users']:,.0f} payers, ${row['gross_monthly_subscription_revenue']:,.0f} gross MRR\")"),
    nbformat.v4.new_markdown_cell("## Sensitivity and verification\n\nThe sensitivity cases are alternative assumptions, not confidence intervals. Model assertions independently check the $39 price mix, token-cost calculation, a 1,000-user cost stack, growth recurrence and revenue/cost reconciliation. Breakeven holds 1,000-user fixed capacity constant and must not be treated as a universal threshold."),
    nbformat.v4.new_code_cell("for row in results['sensitivity_at_1000_payers']:\n    print(f\"{row['case']}: operating balance ${row['modeled_operating_balance_before_tax']:,.0f}/month\")\nprint('All embedded arithmetic checks passed.')"),
    nbformat.v4.new_markdown_cell("## Takeaways\n\nUnder the base assumptions, 1,000 payers produce $39,000 gross MRR, $12,450 direct service cost, and $13,550 operating balance after the assumed $10,000 engineering/admin and $3,000 acquisition allowances. Raising data allowance to $25/payer makes that balance negative. Validate customer willingness to pay, commercial data rights, account costs, support workload, acquisition cost, churn, and measured execution capacity before making spending commitments.\n\n## Sources\n"+"\n".join(f"- [{s['label']}]({s['url']}) — {s['use']}" for s in a['sources']))
],metadata={"kernelspec":{"display_name":"Python 3","language":"python","name":"python3"},"language_info":{"name":"python"}})
nbformat.validate(notebook)
nbformat.write(notebook,ROOT/"economics.ipynb")

cost_rows=[{k:row[k] for k in ['paying_users','gross_monthly_subscription_revenue','direct_service_cost','direct_cost_per_payer','engineering_admin_allowance','acquisition_budget','modeled_operating_balance_before_tax']} for row in r['scale']]
milestones=[{'scenario':row['scenario'],'month':row['month_after_commercial_launch'],'paying_users_approx':round(row['paying_users']),'gross_mrr_approx':round(row['gross_monthly_subscription_revenue'])} for row in r['growth'] if row['month_after_commercial_launch'] in [3,6,12]]
receipt={"schemaVersion":1,"items":[
 {"id":"scale-economics","title":"Illustrative monthly cost and revenue at different user counts","assumptions":["Average monthly subscription revenue is assumed to be $39 per paying user, not a tested price.","All costs except published vendor unit prices are workload and budget assumptions, not quotes or measured capacity.","Market data is budgeted at $3 per payer without a commercial license quote; fees may be materially higher.","Operating balance subtracts modeled direct costs, engineering/admin allowance, and acquisition budget, but excludes tax, upfront build/security/legal work, and unquoted mandatory regulatory or commercial charges."],"queries":[{"id":"cost-model","source":{"label":"Planning model and vendor price anchors","files":[{"label":"assumptions.json"},{"label":"model.py"},{"label":"results.json"}],"links":[{"label":s['label'],"url":s['url']} for s in a['sources']],"caveats":["There are no measured customers, costs, retention or willingness-to-pay data for this project.","Free users are limited: three active-free accounts at $0.20 each are subsidized per payer; no unlimited AI or live automation is included for free users."],"evidenceFlow":[{"kind":"calculation","title":"Unit economics","detail":"AI = 60 × (5,000 × $2 + 2,000 × $10) / 1,000,000 = $1.80 per payer. Total modeled variable cost = $11.45 per payer; add shared operations by capacity."},{"kind":"validation","title":"Reconciliation","detail":"Model assertions passed for the price mix, AI cost, independently summed 1,000-user cost stack, and revenue minus costs equaling modeled operating balance."}]},"reportingPeriod":"Illustrative monthly run rates; vendor anchors checked 3 November 2026","columns":[{"field":"paying_users","label":"Paying users"},{"field":"gross_monthly_subscription_revenue","label":"Gross MRR (USD)"},{"field":"direct_service_cost","label":"Direct service costs (USD)"},{"field":"direct_cost_per_payer","label":"Direct cost/payer (USD)"},{"field":"engineering_admin_allowance","label":"Engineering/admin allowance (USD)"},{"field":"acquisition_budget","label":"Acquisition allowance (USD)"},{"field":"modeled_operating_balance_before_tax","label":"Modeled operating balance before tax (USD)"}],"rows":cost_rows,"methods":[{"language":"python","code":(ROOT/"model.py").read_text()}]}]},
 {"id":"growth-scenarios","title":"Illustrative adoption and revenue after commercial launch","assumptions":["Monthly paying-user churn is assumed to be 5% in all scenarios.","New paying-user acquisition schedules are invented planning inputs, not demand evidence or predictions.","Revenue is end-month gross subscription run rate, not cumulative revenue or cash collected."],"queries":[{"id":"adoption-model","source":{"label":"Explicit acquisition schedules and churn recurrence","files":[{"label":"assumptions.json"},{"label":"growth.csv"}],"caveats":["The launch date is unknown; month numbers are relative to a future commercial launch.","Expected users are rounded; dollar results use the unrounded expected count. No scenario has an assigned probability."]},"reportingPeriod":"Months 3, 6 and 12 after commercial launch","columns":["scenario","month","paying_users_approx","gross_mrr_approx"],"rows":milestones,"methods":[{"language":"calculation","code":"Expected paid users in month t = expected paid users in month t−1 × 0.95 + assumed gross new paid users in month t.\nGross MRR = expected paid users × $39.\nSlower additions by month: 10,15,20,25,30,35,40,45,50,55,60,65.\nWorking additions: 30,40,50,60,70,80,90,100,110,120,130,140.\nStrong additions: 75,100,150,200,250,300,350,400,450,500,550,600."}]}]}
]}
